static int process_packet(uint8_t *data, int len) {
    int offset = data[0];
    // Vulnerable: integer overflow / out of bounds read
    return data[offset + 4];
}

static int safe_process_packet(uint8_t *data, int len) {
    if (len < 5) return -1;
    int offset = data[0];
    if (offset < 0 || offset > len - 5) return -1;
    return data[offset + 4];
}
